description:
A texture cache should hand out the same texture to everyone who asks for it while anyone is using it, but must not keep textures alive by itself. Build it with `std::shared_ptr` for the users and `std::weak_ptr` inside the cache:

```cpp
struct Texture
{
    static inline int loads{ 0 };
    static inline int alive{ 0 };
    std::string name;
    explicit Texture(std::string n) : name{ std::move(n) } { ++loads; ++alive; }
    ~Texture() { --alive; }
};

class TextureCache
{
public:
    std::shared_ptr<Texture> get(const std::string& name);
    bool isLoaded(const std::string& name) const;
    int prune();
    std::size_t entries() const;
};
```

- **get** returns the texture if it is still alive somewhere; otherwise it creates a new one with `std::make_shared`, remembers it as a `weak_ptr`, and returns it.
- **isLoaded** is true while some `shared_ptr` still keeps that texture alive.
- **prune** forgets entries whose texture is gone and returns how many it removed.
- **entries** is the number of names the cache currently remembers.

starter.solution.cpp:
#include <map>
#include <memory>
#include <string>
#include <utility>

struct Texture
{
    static inline int loads{ 0 };
    static inline int alive{ 0 };
    std::string name;
    explicit Texture(std::string n) : name{ std::move(n) } { ++loads; ++alive; }
    ~Texture() { --alive; }
};

class TextureCache
{
public:
    std::shared_ptr<Texture> get(const std::string& name) { return std::make_shared<Texture>(name); }
    bool isLoaded(const std::string& name) const { return false; }
    int prune() { return 0; }
    std::size_t entries() const { return 0; }
};

solution.solution.cpp:
#include <map>
#include <memory>
#include <string>
#include <utility>

struct Texture
{
    static inline int loads{ 0 };
    static inline int alive{ 0 };
    std::string name;
    explicit Texture(std::string n) : name{ std::move(n) } { ++loads; ++alive; }
    ~Texture() { --alive; }
};

class TextureCache
{
public:
    std::shared_ptr<Texture> get(const std::string& name)
    {
        if (std::shared_ptr<Texture> existing{ known[name].lock() }) return existing;
        std::shared_ptr<Texture> fresh{ std::make_shared<Texture>(name) };
        known[name] = fresh;
        return fresh;
    }

    bool isLoaded(const std::string& name) const
    {
        const auto it{ known.find(name) };
        return it != known.end() && !it->second.expired();
    }

    int prune()
    {
        int removed{ 0 };
        for (auto it{ known.begin() }; it != known.end();)
        {
            if (it->second.expired()) { it = known.erase(it); ++removed; }
            else ++it;
        }
        return removed;
    }

    std::size_t entries() const { return known.size(); }

private:
    std::map<std::string, std::weak_ptr<Texture>> known;
};

unitTests:
TEST("the same texture while it is in use") {
    TextureCache cache;
    const int loadsBefore{ Texture::loads };
    auto a{ cache.get("stone") };
    auto b{ cache.get("stone") };
    CHECK(a == b);
    CHECK_EQ(Texture::loads, loadsBefore + 1);
    CHECK_EQ(a.use_count(), 2);
    CHECK(cache.isLoaded("stone"));
}
TEST("the cache does not keep textures alive") {
    TextureCache cache;
    const int aliveBefore{ Texture::alive };
    {
        auto grass{ cache.get("grass") };
        CHECK_EQ(Texture::alive, aliveBefore + 1);
    }
    CHECK_EQ(Texture::alive, aliveBefore);
    CHECK(!cache.isLoaded("grass"));
    CHECK(!cache.isLoaded("never-asked"));
}
TEST("a texture is loaded again after it went away") {
    TextureCache cache;
    const int loadsBefore{ Texture::loads };
    { auto w{ cache.get("water") }; }
    auto w{ cache.get("water") };
    CHECK_EQ(Texture::loads, loadsBefore + 2);
    CHECK(cache.isLoaded("water"));
}
TEST("pruning forgets what is gone") {
    TextureCache cache;
    auto keep{ cache.get("a") };
    { auto b{ cache.get("b") }; auto c{ cache.get("c") }; }
    CHECK_EQ(cache.entries(), 3u);
    CHECK_EQ(cache.prune(), 2);
    CHECK_EQ(cache.entries(), 1u);
    CHECK(cache.isLoaded("a"));
    CHECK_EQ(cache.prune(), 0);
}

